function FlagIcon() { return <CircleHelp size={16} /> }

function ActivityPage() {
  const { state } = useApp()
  const [range, setRange] = useState<30 | 90 | 365>(365)
  const summary = activitySummary(state.activity, range)
  const visibleActivity = state.activity.filter((event) => Date.now() - new Date(event.timestamp).getTime() <= range * 86400000).sort((a, b) => b.timestamp.localeCompare(a.timestamp))
  const daily = Array.from({ length: 7 }, (_, index) => { const date = new Date(); date.setHours(12, 0, 0, 0); date.setDate(date.getDate() - (6 - index)); const key = getDateKey(date); return { label: date.toLocaleDateString('en-US', { weekday: 'short' }), value: state.activity.filter((event) => getDateKey(event.timestamp) === key).reduce((sum, event) => sum + event.contributionPoints, 0) } })
  const attempted = state.activity.filter((event) => event.type === 'question_attempted').length
  return <div className="page"><PageHeader eyebrow="Progress & analytics" title="Your learning activity" description="Every meaningful action becomes evidence you can use to plan the next one." actions={<div className="range-switcher">{([30, 90, 365] as const).map((item) => <button className={range === item ? 'selected' : ''} key={item} onClick={() => setRange(item)}>{item}d</button>)}</div>} /><div className="metric-grid metric-grid-5"><Metric label="Active days" value={summary.activeDays} detail={`Last ${range} days`} tone="green" /><Metric label="Total activity" value={summary.totalActivities} detail="In selected range" /><Metric label="Questions attempted" value={summary.totalQuestions} detail="Meaningful attempts" /><Metric label="Current streak" value={`${summary.currentStreak} days`} detail="Yesterday counts" tone="amber" /><Metric label="Longest streak" value={`${summary.longestStreak} days`} detail="Selected range" /></div><Card className="activity-heatmap-card"><SectionHeading title="Contribution calendar" description="Seeded demo events and current-session activity are shown together." /><ContributionHeatmap activity={state.activity} days={range} /></Card><div className="analytics-grid"><Card><SectionHeading title="Last 7 days" description="Points by day" /><BarChart data={daily} /></Card><Card><SectionHeading title="Activity mix" description="What your learning time includes" /><div className="activity-mix"><div><Donut value={Math.round((attempted / Math.max(1, state.activity.length)) * 100)} label="attempts" color="#65b985" /></div><div className="mix-legend"><span><i className="dot dot-green" /> Questions attempted <b>{attempted}</b></span><span><i className="dot dot-amber" /> Lessons completed <b>{state.activity.filter((event) => event.type === 'lesson_completed').length}</b></span><span><i className="dot dot-blue" /> Mistakes reviewed <b>{state.activity.filter((event) => event.type === 'mistake_reviewed').length}</b></span></div></div></Card></div><Card><SectionHeading title="Activity history" description={`${visibleActivity.length} recorded events · demo and current-session activity`} /><div className="history-table"><div className="history-head"><span>Activity</span><span>Concept</span><span>Source</span><span>Date</span><span>Points</span></div>{visibleActivity.slice(0, 18).map((event) => <div className="history-row" key={event.id}><span><div className="activity-icon">{event.type === 'lesson_completed' ? <BookOpen size={14} /> : event.type === 'mistake_reviewed' ? <RefreshCcw size={14} /> : <CheckCircle2 size={14} />}</div><strong>{event.metadata?.label ?? activityLabel(event.type)}</strong></span><span>{event.conceptId ? getConcept(event.conceptId)?.name : '—'}</span><span><Badge tone={event.isDemo ? 'neutral' : 'green'}>{event.isDemo ? 'Seeded demo' : 'This session'}</Badge></span><span>{new Date(event.timestamp).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}</span><span className="points">+{event.contributionPoints}</span></div>)}</div></Card></div>
}

